import {ToolRegistry} from './registry.js';

describe('tool validator interoperability', () => {
  it('rejects a wrong typed field without exposing its value specs/hal-engine-tool-input-validation/spec.md#2', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'ok');
    registry.register(
      {name: 'forecast', description: 'Forecast', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}},
      execute
    );
    const response = await registry.execute('forecast', {location: 123456});
    expect(response.result).toMatch(/location.*string/);
    expect(response.result).not.toContain('123456');
    expect(execute).not.toHaveBeenCalled();
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.interop.test.ts"
